// ---------- logic ----------
export function codePoints(str) { return Array.from(str).map(c => c.codePointAt(0)); }
export function hex(cp) { return "U+" + cp.toString(16).toUpperCase().padStart(4, "0"); }
export function wordsOf(line) { return line.split(/\s+/).filter(Boolean); }
// CONNECTORS (Alexis, 10:5x PM PT, via the parent): "The is not a word" / "The are and then so thus".
// Read as: these are NOT words in the dimension chains. Her text stays intact everywhere it is displayed; connectors are
// left out only of word counts, word lists, derived words, crossings, shared-word lists and the per-dimension pages.
export const CONNECTORS = { list: ["the", "are", "and", "then", "so", "thus"], status: "investigating, her list may be longer",
  note: "\"is\" is NOT on her list, so it is left as it was (crossings still skip \"is\" as before, by my earlier rule, not by hers). Capitals and letter counts still read the text as written." };
export const isConnector = w => CONNECTORS.list.includes(String(w).toLowerCase().replace(/[^\p{L}]/gu, ""));
export function contentWords(line) { return wordsOf(line).filter(w => !isConnector(w)); }
// A "function" = one letter of a word as written (case kept). Spaces/hyphens are not counted. (INVESTIGATING)
export function letterFunctions(word) {
  return Array.from(word).filter(c => /\p{L}/u.test(c)).map((ch, i) => ({ index: i, ch, cp: ch.codePointAt(0), hex: hex(ch.codePointAt(0)) }));
}
export function functionCount(text) { return wordsOf(text).reduce((n, w) => n + letterFunctions(w).length, 0); }
// PROVISIONAL demonstration value (not a rule): sum of the letters' code points.
export function lineValue(text) { return wordsOf(text).reduce((s, w) => s + letterFunctions(w).reduce((a, f) => a + f.cp, 0), 0); }

// Members bottom-to-top: micro starting dimension first, then chain lines in order. (6 members = 1 + 5)
export function members(col) {
  return [{ kind: "micro", text: col.micro.dimension }].concat(col.chain.map((t, i) => ({ kind: "line", text: t, n: i + 1 })));
}
export function groupPacks(list, sizes) {
  const total = sizes.reduce((a, b) => a + b, 0);
  if (total !== list.length) return { ok: false, total, packs: [] };
  const packs = []; let at = 0;
  for (const s of sizes) { packs.push(list.slice(at, at + s)); at += s; }
  return { ok: true, total, packs };
}
// PROVISIONAL: a pack's 2 bits = (sum of its members' values) mod 4. Demonstration only.
export function packBits(pack) {
  const v = pack.reduce((s, m) => s + lineValue(m.text), 0) % 4;
  return [(v >> 1) & 1, v & 1];
}
export function hexagramBits(packs) { return packs.flatMap(packBits); }
export function parseSizes(s) { return s.split(/[,\s]+/).filter(Boolean).map(Number); }

// ---------- FIVE WRITING SYSTEMS for every spelled-out letter ----------
// Layers, in her order: binary, ASCII, NATO, TRANSLITERATION, UNICODE.
export const LAYERS = ["binary", "ascii", "nato", "translit", "unicode", "color", "sound", "six"];

