// ---------- GENERATIVE MORPHOLOGY, computed from the text only ----------
// A chain line reads "X is Y". The right side Y becomes the left side of the next line.
export function splitLine(text) {
  const t = wordsOf(text), at = t.findIndex(w => w.toLowerCase() === "is");
  if (at < 0) return { left: text, copula: null, right: null };
  return { left: t.slice(0, at).join(" "), copula: t[at], right: t.slice(at + 1).join(" ") || null };
}
export function commonPrefix(a, b) { a = a.toLowerCase(); b = b.toLowerCase(); let i = 0; while (i < a.length && i < b.length && a[i] === b[i]) i++; return i; }
// Each step: how line n hands its right side to line n+1.
export function generateSteps(col) {
  const L = col.chain.map(splitLine), out = [];
  for (let i = 0; i + 1 < L.length; i++) {
    const a = L[i], b = L[i + 1], from = a.right || a.left, fromSide = a.right ? "right" : "left";
    let kind;
    if (b.left.toLowerCase() === from.toLowerCase()) kind = a.right ? "same" : "repeat-left";
    else if (commonPrefix(from, b.left) >= 4) kind = "stem";
    else kind = "different";
    const p = commonPrefix(from, b.left);
    out.push({ from: i + 1, to: i + 2, word: from, fromSide, nextLeft: b.left, kind, stem: kind === "stem" ? from.slice(0, p) : null, restFrom: kind === "stem" ? from.slice(p) : null, restTo: kind === "stem" ? b.left.slice(p) : null });
  }
  return out;
}
// Words that repeat across a column's chain lines (including the root "is").
export function repeatedRoots(col) {
  const m = {};
  col.chain.forEach((t, i) => contentWords(t).forEach(w => { const k = w.toLowerCase(); (m[k] = m[k] || { word: w, lines: [] }).lines.push(i + 1); }));
  return Object.values(m).filter(x => x.lines.length > 1).map(x => ({ word: x.word, count: x.lines.length, lines: x.lines }));
}
// Words of the column's page (chain, starting word, printed natures, keynotes) that share at least 4 first letters but are not the same word.
export function sharedStems(col) {
  const set = new Map();
  const add = w => { const k = w.toLowerCase(); if (/\p{L}{4,}/u.test(w) && k !== "is" && !set.has(k)) set.set(k, w); };
  col.chain.forEach(t => contentWords(t).forEach(add)); contentWords(col.micro.dimension).forEach(add);
  col.micro.natures.forEach(n => contentWords(n).forEach(add)); col.micro.keynoteCell.concat([col.micro.keynoteP5]).forEach(t => contentWords(t).forEach(add));
  const ws = Array.from(set.values()), out = [];
  for (let i = 0; i < ws.length; i++) for (let j = i + 1; j < ws.length; j++) { const p = commonPrefix(ws[i], ws[j]); if (p >= 4) out.push({ a: ws[i], b: ws[j], stem: ws[i].slice(0, p), restA: ws[i].slice(p), restB: ws[j].slice(p) }); }
  return out;
}
// Capital-initial segments of a written word or line: each word that starts with a capital.
export function capitalSegments(text) { return wordsOf(text).map((w, i) => ({ word: w, cap: w[0], isCapital: /\p{Lu}/u.test(w[0]), index: i })).filter(x => x.isCapital); }

