// ---------- CROSSINGS: one dimension's breakdown (its chain lines) crossing the others, computed from the text ----------
// Her words (4:02 PM): "the breakdowns will be crossed by being directly interfering across, then evolution. See, love is in evolution."
export const CROSS_DEFAULT = ["being", "evolution"];
// A crossing = a word of the source line and a word of another dimension's line that start with the same capital letter, or are the same word.
export function crossings(sourceId) {
  const src = DATA.columns.find(c => c.id === sourceId), out = [];
  if (!src) return out;
  src.chain.forEach((t, i) => contentWords(t).forEach(w => {
    for (const c of DATA.columns) { if (c.id === sourceId) continue;
      c.chain.forEach((u, j) => contentWords(u).forEach(v => {
        if (w.toLowerCase() === v.toLowerCase() && w.toLowerCase() !== "is") out.push({ kind: "word", from: sourceId, fromLine: i + 1, fromWord: w, to: c.id, toLine: j + 1, toWord: v, letter: null });
        else if (/\p{Lu}/u.test(w[0]) && /\p{Lu}/u.test(v[0]) && w[0].toLowerCase() === v[0].toLowerCase() && w.toLowerCase() !== v.toLowerCase()) out.push({ kind: "capital", from: sourceId, fromLine: i + 1, fromWord: w, to: c.id, toLine: j + 1, toWord: v, letter: w[0] });
      }));
    }
  }));
  return out;
}

// ---------- CONNECTIONS: every computed link in one model ----------
export function bantuLinks() {
  const out = [], root = "ntu";
  for (const w of registry().filter(x => x.kind === "alt")) {
    const chars = Array.from(w.text), idx = chars.map((c, i) => ({ c: c.toLowerCase(), i })).filter(x => /\p{L}/u.test(x.c)), s = idx.map(x => x.c).join(""), at = s.indexOf(root);
    if (at < 0) continue;
    const rootIdx = idx.slice(at, at + 3).map(x => x.i), before = idx.slice(0, at).map(x => x.i);
    const pre = s.slice(0, at);
    out.push({ wordId: w.id, text: w.text, root: root, rootIdx, prefix: pre, prefixIdx: before, prefixInBook: pre === "ba" ? "a-ba-ntu: ba = noun class prefix (book, printed p.137)" : null });
  }
  return out;
}
export function connectionsModel(scope) {
  scope = scope || "start";
  const reg = registry(), dims = DATA.columns.map(c => c.id);
  const first = {};
  for (const w of reg) { if (!inScope(w, scope)) continue; Array.from(w.text).forEach((ch, i) => { const k = ch.toLowerCase(); if (/\p{L}/u.test(ch) && !first[k]) first[k] = { wordId: w.id, index: i, ch }; }); }
  const edges = pairOverview(scope).map(p => Object.assign({}, p, { refs: p.letters.map(l => first[l]) }));
  const letters = Object.keys(first).sort().map(k => Object.assign({ letter: k, color: letterColor(k.codePointAt(0)), sound: letterHz(k.codePointAt(0)) }, first[k]));
  return {
    dims, order: DIAGONAL_ORDER.slice(), edges, letters,
    sharedWords: sharedWords(reg),
    capitals: DATA.columns.map(capitalsColumn),
    steps: DATA.columns.map(c => ({ id: c.id, steps: generateSteps(c) })),
    diagonal: diagonalColumns().map(c => ({ id: c.id, word: c.micro.dimension, step: c.step })),
    bantu: bantuLinks(), bookMorphs: BOOK_MORPHS
  };
}

