// ---------- SIX-BIT TOKENS grouped 3-2-1, from her Drive file BANTU-321-Swarm-Bridge-v0.2 (bridge.js), experimental transport ----------
// UTF-8 bytes; a byte below 63 is one token; otherwise 63 (escape) then the byte's high 2 bits then its low 6 bits. Each token = six bits = three bigrams.
// Her words: "3 is a bigram 2 is a bigram and 1 is a bigram". The bridge puts the first two bits at level 0. Which bigram is the pack of 3 is INVESTIGATING.
export function encodeTokens(text) {
  const bytes = new TextEncoder().encode(text), out = [];
  for (const b of bytes) { if (b < 63) out.push(b); else out.push(63, b >> 6, b & 63); }
  return out;
}
export function decodeTokens(tokens) {
  const bytes = [];
  for (let i = 0; i < tokens.length; i++) { let v = tokens[i]; if (v === 63) { const hi = tokens[++i], lo = tokens[++i]; v = (hi << 6) | lo; } bytes.push(v); }
  return new TextDecoder("utf-8", { fatal: true }).decode(Uint8Array.from(bytes));
}
export function tokenBits(v) { return v.toString(2).padStart(6, "0"); }
export function tokenLevels(v) { const b = tokenBits(v); return [b.slice(0, 2), b.slice(2, 4), b.slice(4, 6)]; }
export function sixBitOf(text) { const t = encodeTokens(text); return { tokens: t, bits: t.map(tokenBits), levels: t.map(tokenLevels), escaped: t[0] === 63 }; }

