// ---- 1. ALL the words she has given (base list, computed from the page data; nothing added) ----
export function chainTable() {
  return DATA.columns.map(c => {
    const lines = c.chain.map(t => { const m = /^(\S+) is(?: (.+))?$/.exec(t); return { text: t, left: m[1], right: m[2] || null }; });
    const links = lines.slice(1).map((l, i) => ({ line: i + 2, prevRight: lines[i].right, left: l.left, ok: lines[i].right !== null && lines[i].right === l.left }));
    return { id: c.id, dimension: c.dimension, start: c.micro.dimension, lines, links, words: [lines[0].left].concat(lines.map(l => l.right)), natures: c.micro.natures };
  });
}
// slot index 0 = the dimension word, 1..5 = the right-hand word of lines 1..5 as printed (null = printed blank)
export function slotTable() {
  const T = chainTable(), rows = [];
  for (let i = 0; i <= 5; i++) rows.push({ slot: i, words: T.map(t => ({ dim: t.id, word: t.words[i] })) });
  return rows;
}
export function allGivenWords() {
  const T = chainTable();
  return {
    startWords: DATA.columns.map(c => ({ dim: c.id, dimension: c.dimension, start: c.micro.dimension })),
    chains: T.map(t => ({ dim: t.id, lines: t.lines.map(l => l.text), words: t.words })),
    natures: DATA.columns.map(c => ({ dim: c.id, natures: c.micro.natures })),
    keynotes: DATA.columns.map(c => ({ dim: c.id, keynote: c.micro.keynoteCell, p5: c.micro.keynoteP5 })),
    crystalsCenters: DATA.columns.map(c => ({ dim: c.id, crystal: c.micro.crystal, center: c.micro.center, basic: c.basicComponent })),
    vowels: VOWELS, capitalReadings: CAPITAL_READING,
    questionWords: QUESTION_WORDS, whenRules: W_RULES, whenNsnf: W_NSNF,
    notes: { syntaxIsDesign: HER_WORDS.msg12, movementCanBeSyntax: HER_WORDS.msg13, loveIsInEvolution: "See, love is in evolution.", iDefine: KEYNOTE_ANSWER.text, ruling: HER_WORDS.rulingSpace,
      generative: HER_WORDS.msg8, capitalsRule: HER_WORDS.msg9, crossRule: HER_WORDS.msg10 }
  };
}

// ---- 2. her words to dimensions (only by membership in her own chains) ----
export function wordDims() {
  const m = new Map();
  const add = (w, dim, role) => { const k = w.toLowerCase(); if (!m.has(k)) m.set(k, []); const a = m.get(k); if (!a.some(x => x.dim === dim)) a.push({ dim, role }); };
  chainTable().forEach(t => {
    t.lines.forEach((l, i) => { add(l.left, t.id, i === 0 ? "dimension word" : "chain word"); if (l.right) add(l.right, t.id, "chain word"); });
    contentWords(t.start).forEach(w => add(w, t.id, "starting word"));
  });
  return m;
}

// ---- 3. Black Book gates tied to her words (computed whole-word matches, weights: printed keywords 3, line title 2, line text 1) ----
const wordHits = (text, W) => { const out = []; (text.toLowerCase().match(/[a-z]+/g) || []).forEach(w => { if (W.has(w) && !out.includes(w)) out.push(w); }); return out; };
export function gateTies(n) {
  const g = BB_GATES.find(x => x.gate === n), W = wordDims(), hits = [], score = {};
  const put = (word, where, weight) => { const dims = W.get(word).map(x => x.dim); hits.push({ word, where, weight, dims }); dims.forEach(d => score[d] = (score[d] || 0) + weight); };
  const kw = s => s ? s.replace(/^[^.]*\.\s*/, "") : "";
  wordHits(kw(g.center), W).forEach(w => put(w, "center keywords: " + g.center, 3));
  g.signs.forEach(s => wordHits(kw(s), W).forEach(w => put(w, "sign keywords: " + s, 3)));
  if (g.name) wordHits(g.name, W).forEach(w => put(w, "gate name", 2));
  g.lines.forEach(l => { if (!l.text) return; const t = l.title || "", tw = wordHits(t, W); tw.forEach(w => put(w, "line " + l.n + " title", 2)); wordHits(l.text, W).filter(w => !tw.includes(w)).forEach(w => put(w, "line " + l.n + " text", 1)); });
  const isForms = [];
  g.lines.forEach(l => { const m = l.text && /^([A-Za-z]+) is\b/.exec(l.text); if (m && W.has(m[1].toLowerCase())) isForms.push({ line: l.n, word: m[1], dims: W.get(m[1].toLowerCase()).map(x => x.dim), start: l.text.split(/(?<=\w)\.\s/)[0] }); });
  const ranking = Object.keys(score).sort((a, b) => score[b] - score[a]).map(d => ({ dim: d, score: score[d] }));
  return { gate: n, hits, score, ranking, isForms };
}
export function gateTiesAll() { return BB_GATES.map(g => gateTies(g.gate)); }
// her chain lines that appear word for word as the start of a Black Book gate line
export function exactLineMatches() {
  const out = [];
  chainTable().forEach(t => t.lines.forEach((l, i) => BB_GATES.forEach(g => g.lines.forEach(gl => {
    if (!gl.text) return; const head = gl.title ? gl.title.toLowerCase() : "";
    if (head === l.text.toLowerCase()) out.push({ dim: t.id, chainLine: i + 1, her: l.text, gate: g.gate, gateLine: gl.n, pdfPage: g.pdfPage, printedPage: g.printedPage, quote: gl.title });
  }))));
  return out;
}

